  if (btnDownloadModel_ != nullptr) {
    btnDownloadModel_->setEnabled(true);
  }
  if (btnRemoveModel_ != nullptr) {
    btnRemoveModel_->setEnabled(true);
  }
  downloadStatusLabel_->clear();
